const frame=()=>new Promise(r=>requestAnimationFrame(r));
const out=[];
// case A: as shipped. case B: gsfwd1..8 aliased onto gsback cells (IN MEMORY ONLY).
// case C: kheel1..8 aliased onto kpush cells, to prove back+L's row choice.
async function fire(tag, dkeys, tier){
  p1Pick=2;p2Pick=5;startNewGame();roundIntroTimer=0;await frame();await frame();
  const p=player1; if(p.spec.id!==2){out.push({tag,ERR:'not shin'});return;}
  const F=SPRITES.shin.frames; const CELL={}; for(const k in F)(CELL[F[k]]=CELL[F[k]]||[]).push(k);
  for(const k in keys)keys[k]=false;
  p.x=400;p.facing=1;p.stamina=100;p.chakra=100;p.chainComboTier=0;p.attackHasConnected=false;p.connectTime=-1e9;
  const spawned=[];const orig=p.spawnHitbox.bind(p);
  p.spawnHitbox=function(w,h,d,dl,kb,o){spawned.push([Math.round(w),Math.round(h),Math.round(d),+(dl||0).toFixed(2),Math.round(kb||0),Object.keys(o||{}).filter(x=>o[x]===true).sort().join('+')].join('/'));return orig(w,h,d,dl,kb,o);};
  dkeys.forEach(k=>keys[k]=true);
  p.executeAttack(STATE[tier]);
  const dur=p.attackAnim?Math.round(p.attackAnim.dur):0, kick=p.kickKind;
  const seen=[];let proj=0;
  for(let f=0;f<70;f++){dkeys.forEach(k=>keys[k]=true);await frame();dkeys.forEach(k=>keys[k]=true);
    proj=Math.max(proj,(p.projectiles||[]).length);
    if(p.attackAnim)seen.push(spriteFrameIndex(p,F));
    if(!p.isAttackingState()&&f>6)break;}
  dkeys.forEach(k=>keys[k]=false);p.spawnHitbox=orig;
  const u=[...new Set(seen)];
  out.push({tag, kick, box:[...new Set(spawned)].join(' | '), proj, dur,
            projKinds:[...new Set((p.projectiles||[]).map(x=>x.kind))].join(','),
            alias:u.map(i=>(CELL[i]||[]).join('=')).join(' > ')});
}
await fire('A shipped fwd+S', ['KeyD'], 'ATTACK_SPECIAL');
await fire('A shipped back+L', ['KeyA'], 'ATTACK_LIGHT');
