await fire('C +kheel back+L', ['KeyA'], 'ATTACK_LIGHT');
for(let i=1;i<=8;i++) delete Fx['gsfwd'+i];
for(let i=1;i<=5;i++) delete Fx['kheel'+i];
window.__C=out; return 'ok';
